// Process raw string into strongly-typed EmojiItem list
export const ALL_EMOJIS: EmojiItem[] = [];

Object.entries(rawEmojiMap).forEach(([category, items]) => {
  items.forEach(raw => {
    const [emoji, name, keywords] = raw.split('|');
    ALL_EMOJIS.push({
      emoji,
      name: name || category,
      category,
      keywords: `${name} ${keywords || ''} ${category}`.toLowerCase()
    });
  });
});

